-- 054: FCB 2027 evaluation form, from the Google Form "FCB 27 Evaluation form". Every rating lists the highest choice first (Excellent → Poor, Strongly agree → Strongly disagree).
-- It stays closed until the day: open it from Admin → FCB 2027. Safe to run more than once.
insert into public.forms (slug, title, subtitle, description, sensitive, is_open, fields)
values ('fcb27-evaluation', 'Finding Campus Balance 2027 – Participant Evaluation Form', 'FCB 2027 evaluation',
  $q$Thank you for participating in Finding Campus Balance 2027. Please take approximately 3–5 minutes to share your experience. Your feedback will help BCIL Foundation evaluate the program, improve future editions, and understand how the program contributed to your campus experience and personal development. Your responses will be used for program evaluation and reporting.$q$,
  false, false,
$j$[{"key": "s2", "type": "section", "label": "About your participation"}, {"key": "level", "label": "What is your current level of study?", "type": "radio", "required": true, "options": ["Level 100", "Level 200", "Level 300", "Level 400", "Level 500", "Level 600", "Postgraduate", "Other"]}, {"key": "college", "label": "Which college are you affiliated with?", "type": "radio", "required": true, "options": ["College of Agriculture and Natural Sciences", "College of Education Studies", "College of Health and Allied Sciences", "College of Humanities and Legal Studies"]}, {"key": "attended_before", "label": "Have you attended Finding Campus Balance before?", "type": "radio", "required": true, "options": ["Yes", "No"]}, {"key": "activities", "label": "Which FCB 2027 activities did you participate in?", "type": "checkbox", "required": true, "options": ["CV & Cover Letter Clinic", "Digital Safety & Responsibility Session", "Academic Wellbeing Session", "Campus Life Experience Panel", "Mentorship Registration/Engagement", "Other"]}, {"key": "s3", "type": "section", "label": "Session evaluation", "help": "Please rate the FCB 2027 sessions you attended."}, {"key": "rate_cv", "label": "CV & Cover Letter Clinic", "type": "radio", "required": true, "options": ["Excellent", "Very good", "Good", "Fair", "Poor", "Did not attend"]}, {"key": "rate_digital", "label": "Digital Safety & Responsibility Session", "type": "radio", "required": true, "options": ["Excellent", "Very good", "Good", "Fair", "Poor", "Did not attend"]}, {"key": "rate_wellbeing", "label": "Academic Wellbeing Session", "type": "radio", "required": true, "options": ["Excellent", "Very good", "Good", "Fair", "Poor", "Did not attend"]}, {"key": "rate_panel", "label": "Campus Life Experience Panel", "type": "radio", "required": true, "options": ["Excellent", "Very good", "Good", "Fair", "Poor", "Did not attend"]}, {"key": "s3b", "type": "section", "label": "How useful or relevant was each activity to you?"}, {"key": "use_cv", "label": "CV & Cover Letter Clinic", "type": "radio", "required": true, "options": ["Extremely useful", "Very useful", "Moderately useful", "Slightly useful", "Not useful", "Did not attend"]}, {"key": "use_digital", "label": "Digital Safety & Responsibility Session", "type": "radio", "required": true, "options": ["Extremely useful", "Very useful", "Moderately useful", "Slightly useful", "Not useful", "Did not attend"]}, {"key": "use_wellbeing", "label": "Academic Wellbeing Session", "type": "radio", "required": true, "options": ["Extremely useful", "Very useful", "Moderately useful", "Slightly useful", "Not useful", "Did not attend"]}, {"key": "use_panel", "label": "Campus Life Experience Panel", "type": "radio", "required": true, "options": ["Extremely useful", "Very useful", "Moderately useful", "Slightly useful", "Not useful", "Did not attend"]}, {"key": "s4", "type": "section", "label": "Learning & outcomes", "help": "After participating in FCB 2027, indicate how much you agree with the following statements."}, {"key": "agree_digital", "label": "I better understand how to protect myself and behave responsibly in digital spaces.", "type": "radio", "required": true, "options": ["Strongly agree", "Agree", "Neither agree nor disagree", "Disagree", "Strongly disagree"]}, {"key": "agree_stress", "label": "I have practical strategies for managing academic stress and wellbeing.", "type": "radio", "required": true, "options": ["Strongly agree", "Agree", "Neither agree nor disagree", "Disagree", "Strongly disagree"]}, {"key": "agree_challenges", "label": "I better understand how to navigate challenges associated with university life.", "type": "radio", "required": true, "options": ["Strongly agree", "Agree", "Neither agree nor disagree", "Disagree", "Strongly disagree"]}, {"key": "agree_decisions", "label": "I feel better prepared to make decisions about my academic and professional development.", "type": "radio", "required": true, "options": ["Strongly agree", "Agree", "Neither agree nor disagree", "Disagree", "Strongly disagree"]}, {"key": "agree_support", "label": "I know where or from whom I can seek support when I face challenges on campus.", "type": "radio", "required": true, "options": ["Strongly agree", "Agree", "Neither agree nor disagree", "Disagree", "Strongly disagree"]}, {"key": "agree_apply", "label": "I intend to apply something I learned from FCB 2027.", "type": "radio", "required": true, "options": ["Strongly agree", "Agree", "Neither agree nor disagree", "Disagree", "Strongly disagree"]}, {"key": "learned", "label": "What is the most important thing you learned from FCB 2027?", "type": "textarea", "required": true}, {"key": "s5", "type": "section", "label": "Overall program experience"}, {"key": "overall", "label": "Overall, how would you rate Finding Campus Balance 2027?", "type": "radio", "required": true, "options": ["5 · Excellent", "4", "3", "2", "1 · Poor"]}, {"key": "s5b", "type": "section", "label": "Please rate the following aspects of your FCB 2027 experience."}, {"key": "exp_registration", "label": "Registration/check-in process", "type": "radio", "required": true, "options": ["Excellent", "Very good", "Good", "Fair", "Poor", "Not applicable"]}, {"key": "exp_organization", "label": "Organization of the program", "type": "radio", "required": true, "options": ["Excellent", "Very good", "Good", "Fair", "Poor", "Not applicable"]}, {"key": "exp_speakers", "label": "Quality of speakers/resource persons", "type": "radio", "required": true, "options": ["Excellent", "Very good", "Good", "Fair", "Poor", "Not applicable"]}, {"key": "exp_volunteers", "label": "Helpfulness/professionalism of volunteers", "type": "radio", "required": true, "options": ["Excellent", "Very good", "Good", "Fair", "Poor", "Not applicable"]}, {"key": "exp_venue", "label": "Venue and seating arrangements", "type": "radio", "required": true, "options": ["Excellent", "Very good", "Good", "Fair", "Poor", "Not applicable"]}, {"key": "exp_communication", "label": "Communication/information provided", "type": "radio", "required": true, "options": ["Excellent", "Very good", "Good", "Fair", "Poor", "Not applicable"]}, {"key": "exp_experience", "label": "Overall participant experience", "type": "radio", "required": true, "options": ["Excellent", "Very good", "Good", "Fair", "Poor", "Not applicable"]}, {"key": "most_valuable", "label": "Which activity or session was most valuable to you?", "type": "radio", "required": true, "options": ["CV & Cover Letter Clinic", "Digital Safety & Responsibility Session", "Academic Wellbeing Session", "Campus Life Experience Panel", "Mentorship opportunity", "Other"]}, {"key": "recommend", "label": "How likely are you to recommend Finding Campus Balance to another student?", "type": "radio", "required": true, "options": ["5 · Extremely likely", "4", "3", "2", "1 · Not at all likely"]}, {"key": "s6", "type": "section", "label": "Future engagement & improvement"}, {"key": "improve", "label": "What is one thing BCIL Foundation could improve about Finding Campus Balance?", "type": "textarea"}, {"key": "anything_else", "label": "Is there anything else you would like us to know about your FCB 2027 experience?", "type": "textarea"}, {"key": "mentorship", "label": "Are you interested in receiving continued mentorship through BCIL Foundation?", "type": "radio", "required": true, "options": ["Yes", "No"], "help": "If yes, please also complete the FCB 2027 Mentorship Registration form. You'll find it on the FCB 2027 page and under Mentorship in the app."}]$j$::jsonb)
on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, fields = excluded.fields;

-- staff: counts of answers per choice for one form (for the FCB 2027 results view)
create or replace function public.form_tally(p_slug text) returns table (field text, answer text, n int)
language plpgsql stable security definer set search_path = public as $$
begin
  if not is_staff() then raise exception 'Staff only'; end if;
  return query
    select kv.key, kv.value #>> '{}', count(*)::int
    from form_responses r join forms f on f.id = r.form_id, jsonb_each(r.answers) kv
    where f.slug = p_slug and jsonb_typeof(kv.value) = 'string'
    group by 1, 2;
end $$;
grant execute on function public.form_tally(text) to authenticated;

select 'ok' as fcb_evaluation_setup;
